-- tests/test_shine.lua — the shine overlay's seam (modules/Shine.lua, NS.Shine): the looks catalog,
-- the art each look names (generated by tools/gen-shine-textures.py and shipped under
-- media/textures/), Resolve (a look table's flat leaves into the paint's values) and Apply (a pad
-- button's shine over the whole button, in three pieces so a wide button keeps its edges thin). The pad's and the dial's settings rows and their paint are T3's and
-- T4's; this suite drives the seam directly.

local T = _G.QUICKCOMMS_TEST
local test, assertEqual, assertTrue, assertFalse, assertNil =
    T.test, T.assertEqual, T.assertTrue, T.assertFalse, T.assertNil

local function csv(t) return table.concat(t, ",") end

local function exists(path)
    local rel = path:gsub("^Interface\\AddOns\\QuickComms\\", ""):gsub("\\", "/")
    local fh = io.open(T.root .. "/" .. rel .. ".tga", "rb")
    if fh then fh:close() end
    return fh ~= nil, rel
end

-- A pad button, the way modules/Pad_Render.lua dresses one: its plate over the whole button and its
-- icon at ARTWORK, drawn.
local function probe(m, name)
    local btn = m.CreateFrame("Button", name or "QuickCommsShineProbe", m.UIParent)
    local icon = btn:CreateTexture(nil, "ARTWORK")
    icon:SetTexture("Interface\\Icons\\INV_Misc_QuestionMark")
    return btn, icon
end

local function shineOf(NS, look, extra)
    local cfg = { shineLook = look, shineStrength = 85, shineTint = { r = 1, g = 0.5, b = 0.25, a = 1 } }
    for k, v in pairs(extra or {}) do cfg[k] = v end
    return NS.Shine.Resolve(cfg)
end

-- A piece's anchors as "POINT>rel:RELPOINT", in order.
local function anchors(t, names)
    local out = {}
    for i = 1, #t.__points do
        local p = t.__points[i]
        out[#out + 1] = p[1] .. ">" .. (names[p[2]] or "?") .. ":" .. tostring(p[3])
    end
    return table.concat(out, " ")
end

local function shown(set)
    return set ~= nil and (set.left:IsShown() or set.mid:IsShown() or set.right:IsShown())
end

test("shine: the catalog lists None and the seven looks", function()
    local NS = T.newAddon()
    -- red under: no modules/Shine.lua (NS.Shine is nil)
    assertTrue(NS.Shine ~= nil, "NS.Shine")
    -- red under: no Gloss fade (owner, 2026-10-21), right after Gloss cap
    assertEqual(csv(NS.Shine.LOOKS), "none,gloss,glossfade,orb,frost,fluid,bevel,rim")
    assertNil(NS.Shine.Texture("pad", "none"), "None draws nothing")
    assertNil(NS.Shine.Texture("pad", "satin"), "an unknown look draws nothing")
end)

test("shine: every catalog path exists", function()
    local NS = T.newAddon()
    local Sh = NS.Shine
    local paths = {}
    local function add(p, what)
        assertTrue(type(p) == "string", what .. ": a path")
        paths[#paths + 1] = p
    end
    for i = 2, #Sh.LOOKS do add(Sh.Texture("pad", Sh.LOOKS[i]), "pad " .. Sh.LOOKS[i]) end
    add(Sh.Texture("pad", "fluid-bloom1"), "pad bloom 1")
    add(Sh.Texture("pad", "fluid-bloom2"), "pad bloom 2")
    for _, name in ipairs({ "gloss", "glossfade", "frost", "rim" }) do
        add(Sh.Texture("dial", name), "dial " .. name)
    end
    for _, name in ipairs({ "bead", "fluid-bloom1", "fluid-bloom2" }) do add(Sh.Texture("sprite", name), "sprite " .. name) end
    -- red under: the retired art still named (the orb's dots, Bevel's upright light, the disc blooms)
    for _, name in ipairs({ "spot", "glow", "streak" }) do assertNil(Sh.Texture("sprite", name), "retired sprite " .. name) end
    for _, name in ipairs({ "bevel", "bevel-edge", "fluid-bloom1", "fluid-bloom2" }) do
        assertNil(Sh.Texture("dial", name), "retired dial art " .. name)
    end
    assertNil(Sh.Edge("soft", 4), "the soft edge sets are retired")
    for n = 1, 12 do
        add(Sh.Edge("rim", n), "rim " .. n)
        add(Sh.Edge("streak", n), "streak " .. n)
        add(Sh.Edge("bevel", n), "bevel " .. n)
        assertEqual(Sh.Texture("edge-rim", n), Sh.Edge("rim", n), "Texture reaches the edge sets")
        assertEqual(Sh.Texture("edge-bevel", n), Sh.Edge("bevel", n))
        assertTrue(Sh.Edge("streak", n):find("shine%-edge%-streak%-" .. n .. "$") ~= nil, Sh.Edge("streak", n))
    end
    assertEqual(Sh.Edge("rim", 20), Sh.Edge("rim", 12), "a count past the dial's most slices clamps")
    assertEqual(#paths, 52, "the generator's 52 files")
    for _, p in ipairs(paths) do
        local ok, rel = exists(p)
        assertTrue(ok, rel)
    end
end)

test("shine: Resolve", function()
    local NS, m = T.enableAddon()
    local Sh = NS.Shine
    local s = Sh.Resolve({})
    assertEqual(s.look, "none", "nothing set: None")
    assertEqual(s.alpha, 0.85, "the default Strength, 85")
    assertEqual(csv(s.tint), "1,1,1", "white by default")
    assertEqual(csv(s.bloomA), "1,0.604,0.835", "#ff9ad5")
    assertEqual(csv(s.bloomB), "0.541,1,0.757", "#8affc1")
    assertEqual(Sh.Resolve({ shineLook = "orb", shineStrength = 0 }).alpha, 0, "Strength 0: alpha 0")
    assertEqual(Sh.Resolve({ shineLook = "orb", shineStrength = 50 }).alpha, 0.5)
    assertEqual(Sh.Resolve({ shineLook = "orb", shineStrength = 250 }).alpha, 1, "clamped")
    assertEqual(Sh.Resolve({ shineLook = "satin" }).look, "none", "an unknown look is None")
    m.RAID_CLASS_COLORS = { MAGE = { r = 0.25, g = 0.75, b = 0.5 } }
    s = Sh.Resolve({ shineLook = "fluid", shineTint = { r = 1, g = 1, b = 1, a = 1 }, useClassColorShineTint = true,
        shineBloomA = { r = 0, g = 0, b = 0, a = 1 }, useClassColorShineBloomB = true })
    -- red under: the tint read without its Use class color companion
    assertEqual(csv(s.tint), "0.25,0.75,0.5", "class color tint uses the class color")
    assertEqual(csv(s.bloomA), "0,0,0", "bloom A keeps its swatch")
    assertEqual(csv(s.bloomB), "0.25,0.75,0.5", "bloom B takes the class color")
end)

test("shine: Apply covers the whole button in three pieces", function()
    local NS, m = T.enableAddon()
    local btn = probe(m)
    NS.Shine.Apply(btn, shineOf(NS, "orb"), 120, 24)
    local set = btn.qcShine
    -- red under: Apply laying one texture over the icon (SetAllPoints)
    assertTrue(set ~= nil and set.left ~= nil and set.mid ~= nil and set.right ~= nil, "three pieces")
    local names = { [btn] = "btn", [set.left] = "left", [set.right] = "right" }
    for _, key in ipairs({ "left", "mid", "right" }) do
        local t = set[key]
        assertTrue(t:IsShown(), key .. " shown")
        assertEqual(t.__layer .. "/" .. tostring(t.__sublevel), "ARTWORK/5", key .. ": over the icon, under the label")
        assertTrue(t.__texture:find("shine%-pad%-orb$") ~= nil, tostring(t.__texture))
        assertEqual(csv(t.__color), "1,0.5,0.25,0.85", key .. ": the tint, faded by Strength")
        assertEqual(t.__blend, "BLEND")
    end
    assertEqual(anchors(set.left, names), "TOPLEFT>btn:TOPLEFT BOTTOMLEFT>btn:BOTTOMLEFT", "the left cap")
    assertEqual(anchors(set.right, names), "TOPRIGHT>btn:TOPRIGHT BOTTOMRIGHT>btn:BOTTOMRIGHT", "the right cap")
    assertEqual(anchors(set.mid, names), "TOPLEFT>left:TOPRIGHT BOTTOMRIGHT>right:BOTTOMLEFT", "the middle")
    assertEqual(set.left.__size[1], 12, "a cap is half the button's height wide")
    assertEqual(set.right.__size[1], 12)
    assertEqual(csv(set.left.__texCoord), "0,0.5,0,1", "the art's left half")
    assertEqual(csv(set.right.__texCoord), "0.5,1,0,1", "the art's right half")
    assertEqual(csv(set.mid.__texCoord), "0.49,0.51,0,1", "the art's middle, stretched")
    assertNil(btn.qcShineBloom1, "no blooms made for Glass orb")
end)

test("shine: a square button is the art whole", function()
    local NS, m = T.enableAddon()
    local btn = probe(m)
    NS.Shine.Apply(btn, shineOf(NS, "gloss"), 40, 40)
    local set = btn.qcShine
    assertTrue(set.left:IsShown() and set.right:IsShown(), "both caps")
    assertFalse(set.mid:IsShown(), "no middle on a square button")
    assertEqual(set.left.__size[1], 20)
    NS.Shine.Apply(btn, shineOf(NS, "gloss"), 30, 50)
    assertEqual(set.left.__size[1], 15, "a tall button: each cap half its width")
    assertFalse(set.mid:IsShown())
    NS.Shine.Apply(btn, shineOf(NS, "gloss"), 120, 24)
    assertTrue(set.mid:IsShown(), "wide again: the middle returns")
end)

test("shine: blooms only for fluid", function()
    local NS, m = T.enableAddon()
    local btn = probe(m)
    NS.Shine.Apply(btn, shineOf(NS, "fluid", { shineBloomA = { r = 1, g = 0, b = 0, a = 1 },
        shineBloomB = { r = 0, g = 0, b = 1, a = 1 }, shineStrength = 50 }), 120, 24)
    local b1, b2 = btn.qcShineBloom1, btn.qcShineBloom2
    assertTrue(b1 ~= nil and b2 ~= nil, "Fluid glass makes its blooms")
    assertTrue(shown(btn.qcShine) and shown(b1) and shown(b2))
    assertTrue(btn.qcShine.left.__texture:find("shine%-pad%-fluid$") ~= nil)
    for _, key in ipairs({ "left", "mid", "right" }) do
        assertEqual(b1[key].__layer .. "/" .. b1[key].__sublevel, "ARTWORK/6", "bloom 1 " .. key)
        assertEqual(b2[key].__layer .. "/" .. b2[key].__sublevel, "ARTWORK/7", "bloom 2 " .. key)
        assertTrue(b1[key].__texture:find("shine%-pad%-fluid%-bloom1$") ~= nil)
        assertTrue(b2[key].__texture:find("shine%-pad%-fluid%-bloom2$") ~= nil)
        assertEqual(csv(b1[key].__color), "1,0,0,0.5", "bloom A")
        assertEqual(csv(b2[key].__color), "0,0,1,0.5", "bloom B")
        assertEqual(b1[key].__blend, "BLEND")
    end
    NS.Shine.Apply(btn, shineOf(NS, "orb"), 120, 24)
    -- red under: a look change that repaints qcShine only (the blooms left behind)
    assertTrue(shown(btn.qcShine))
    assertFalse(shown(b1), "orb hides bloom 1")
    assertFalse(shown(b2), "orb hides bloom 2")
    NS.Shine.Apply(btn, shineOf(NS, "none"), 120, 24)
    assertFalse(shown(btn.qcShine) or shown(b1) or shown(b2), "None hides all three")
    NS.Shine.Apply(btn, nil, 120, 24)
    assertFalse(shown(btn.qcShine), "no shine table: nothing drawn")
end)

test("shine: the button's own size when none is given", function()
    local NS, m = T.enableAddon()
    local btn = probe(m)
    btn.GetWidth = function() return 80 end
    btn.GetHeight = function() return 20 end
    NS.Shine.Apply(btn, shineOf(NS, "rim"))
    assertEqual(btn.qcShine.left.__size[1], 10, "half its height")
    assertTrue(btn.qcShine.mid:IsShown())
end)
